before:
Complete local C++ example; the app itself does not execute it:
```cpp
#include <iostream>

int main()
{
    int choice{2};
    switch (choice)
    {
    case 1: std::cout << "Read\n"; break;
    case 2: std::cout << "Write\n"; break;
    default: std::cout << "Help\n"; break;
    }
}

```

